A Mean Function

my_mean_function = function(y) {

  n = length(y)
  sum = 0
  for (i in 1:n) sum = sum + y[i]

  mean = sum / n

  return(mean)

}

MSE Function

mse &lt;- function(par, y, X) {

  # the weights are stored in "par", the length of that vector depends
  # on the number of columns in X (number of features)

  # predicted value
  pred = X %*% par

  # mean squared error
  mse = mean((y - pred)**2)

  return(mse)

}

Ridge Objective

mse_ridge &lt;- function(par, y, M, X) {

  b = par[1:ncol(X)]
  mu = X %*% b

  u = par[(ncol(X) + 1):(length(par) - 1)]
  pred = mu + M %*% u

  mse = mean((y - pred)**2)
  ridge_param = par[length(par)]
  ridge = ridge_param * sum(u**2)

  criteria = mse + ridge

  if(ridge_param &lt; 0) {
    criteria = 9999999
  }

  return(criteria)
}

Stan Mixture Program

hcode =
"
data {
    int&lt;lower=1&gt; N;
    int&lt;lower=1&gt; k;
    real y[N];
}
parameters {
    simplex[k] theta;
    real mu[k];
    real&lt;lower=0&gt; tau[k];
}
model {
    real ps[k];
    for (i in 1:k){
        mu[i] ~ normal(0, 1.0e+2);
    }
    for(i in 1:N){
        for(j in 1:k){
            ps[j] &lt;- log(theta[j]) + normal_log(y[i], mu[j], tau[j]);
        }
        increment_log_prob(log_sum_exp(ps));
    }
    tau ~ cauchy(0,5);
}
"

Mixture Probability Helper

GetProbNormalMixture &lt;- function(y, lambda, mu, sigma) {

  lik &lt;- array(as.numeric(NA), dim = c(length(y), length(lambda)))
  for(i in 1:length(lambda)) lik[,i] &lt;- lambda[i] * dnorm(y,mu[i],sigma[i])
  probs &lt;- lik / rowSums(lik)
  return(probs)

}

dnormLambda &lt;- function(x, lambda, mu , sigma) {
  return(lambda * dnorm(x, mu, sigma))
}

4.4 Cross Validation
In order to assess the performance of our genomic prediction models, we can run a cross validation scheme, in which we train marker effects with a subset of the data and predict the EBVs of the left out samples based on the training model.

# define function to create cross validation samples
cCV &lt;- function(y, folds=5, reps=1, matrix=FALSE, seed=NULL) {

  if(!is.vector(y)) stop("y must be a vector")
  if(folds &lt; 2) stop("'folds' must be larger than one")
  if(reps &lt; 1) reps = 1

  reps = as.integer(reps)
  folds = as.integer(folds)

  isy &lt;- (1:length(y))[!is.na(y)]

  n_vec &lt;- rep(NA,folds)
  start &lt;- rep(NA,folds)
  end &lt;- rep(NA,folds)

  n_vec[1:(folds-1)] &lt;- round(length(isy)/folds,digits=0)
  n_vec[folds] &lt;- length(isy) - sum(n_vec[1:(folds-1)])


  for(j in 1:folds) {

    if(j==1) {

      start[j] = 1

    } else {

      start[j] = end[j-1]+1

    }

    end[j] = sum(n_vec[1:j])
  }

  count=0
  cv_pheno &lt;- list(folds*reps)

  if(missing(seed)) seed = as.integer((as.double(Sys.time())*1000+Sys.getpid()) %% 2^31)
  set.seed(seed)

  for(i in 1:reps) {

    ids &lt;- sample(isy,length(isy),replace=F)

    for(j in 1:folds) {

      count=count+1
      y_temp = y
      y_temp[ids[start[j]:end[j]]] &lt;- NA
      cv_pheno[[count]] &lt;- y_temp

    }

  }


  if(matrix) {

    return(matrix(unlist(cv_pheno),nrow=length(y),ncol=length(cv_pheno),byrow=FALSE))

  } else {

    return(cv_pheno)

  }

}

