Finding Mean And Standard Deviation

sdlik &lt;- function(x) {
  res &lt;- 0
  if (x &gt; 0) res = 1
  return(log(res))
}

lik &lt;- function(par, y) {
  mean = par[1]
  sd = par[2]

  L2 &lt;- sdlik(sd)
  if (!is.finite(L2)) return(Inf)

  L1 &lt;- dnorm(x = y, mean = mean, sd = sd, log = TRUE)
  return(-sum(L1 + L2))
}

