library(mvtnorm)

corlik &lt;- function(x) {
  res &lt;- 0
  if (x &gt;= -1 & x &lt;= 1) res = 1
  return(log(res))
}

varlik &lt;- function(x) {
  res &lt;- 0
  if (x &gt; 0) res = 1
  return(log(res))
}

Build Sigma

lik &lt;- function(par, y) {
  L2 &lt;- corlik(par[5])
  L3 &lt;- varlik(par[3])
  L4 &lt;- varlik(par[4])
  if (!all(is.finite(c(L2, L3, L4)))) return(Inf)

  covAB &lt;- par[5] * (sqrt(par[3]) * sqrt(par[4]))
  sigma &lt;- array(c(par[3], covAB, covAB, par[4]), dim = c(2, 2))

  L1 &lt;- tryCatch(
    dmvnorm(x = y, mean = c(par[1], par[2]), sigma = sigma, log = TRUE),
    error = function(e) -Inf
  )
  if (!all(is.finite(L1))) return(Inf)

  return(-sum(L1 + L2 + L3 + L4))
}

Animal Model Likelihood
\[
\mathbf{y}
=
\mathbf{X}\mathbf{b}
+ \mathbf{a}
+ \mathbf{e}
\]
\[
\mathbf{y} \sim MVN(\mathbf{X}\mathbf{b},
\mathbf{A}\sigma_a^2 + \mathbf{I}\sigma_e^2)
\]

Animal Likelihood Function

lik &lt;- function(par, y, X, A) {
  L2 &lt;- varlik(par[1])
  L3 &lt;- varlik(par[2])
  if (!all(is.finite(c(L2, L3)))) return(Inf)

  b &lt;- matrix(c(par[3:(2 + ncol(X))]), ncol = 1)
  G &lt;- A * par[2]
  R &lt;- diag(length(y)) * par[1]
  V &lt;- G + R
  mu &lt;- X %*% b

  L1 &lt;- tryCatch(
    dmvnorm(x = y, mean = as.numeric(mu), sigma = V, log = TRUE),
    error = function(e) -Inf
  )
  if (!all(is.finite(L1))) return(Inf)

  return(-sum(L1 + L2 + L3))
}
